<template><view class="page"><PromptHost /><view class="wrap"><MobileHeader title="我的"/><view class="account-bar"><view class="avatar"><AppIcon name="user" :size="27" color="#4b68c6"/></view><view class="identity"><text class="name">{{session.identity?.user.nickname||'未登录'}}</text><text class="status">{{session.identity?'已登录':'账号登录后同步通知与工作'}}</text></view><button class="account-action" :disabled="busy" @tap="accountAction">{{session.identity?'退出登录':'登录'}}</button></view><view class="permission-row" role="button" aria-label="权限设置" @tap="permissions"><view class="row-icon"><AppIcon name="shield" :size="21" color="#5b6d91"/></view><text>权限设置</text><AppIcon name="chevron-right" :size="17" color="#9aa4b5"/></view><DiagnosticLogs/><!-- #ifdef APP-PLUS --><AppUpdateRow/><!-- #endif --><!-- #ifdef H5 --><view class="web-update"><view><text>检查更新</text><text class="version">当前版本 {{version}}</text></view><text class="native-only">App 内可用</text></view><!-- #endif --></view><TabBar current="mine"/></view></template>
<script setup lang="ts">
import PromptHost from '@/components/prompt/PromptHost.vue';import {ref} from 'vue';import MobileHeader from '@/components/MobileHeader.vue';import TabBar from '@/components/TabBar.vue';import AppIcon from '@/components/AppIcon.vue';import DiagnosticLogs from '@/components/DiagnosticLogs.vue';import AppUpdateRow from '@/components/AppUpdateRow.vue';import {session,openLogin,signOut} from '@/platform';const version=__APP_VERSION_NAME__,busy=ref(false);function permissions(){uni.navigateTo({url:'/pages/permissions/index'});}async function accountAction(){if(busy.value)return;if(!session.identity){openLogin('/pages/mine/index');return;}uni.showModal({title:'退出登录',content:'确认退出当前账号？',success:async r=>{if(!r.confirm)return;busy.value=true;try{await signOut();}catch{uni.showToast({title:'退出失败，请重试',icon:'none'});}finally{busy.value=false;}}});}</script>
<style scoped>.page{min-height:100vh;background:#f7f8fc;padding-bottom:calc(110px + env(safe-area-inset-bottom))}.wrap{max-width:500px;margin:auto;padding:0 16px}.account-bar{display:flex;align-items:center;gap:14px;background:#fff;border-radius:20px;padding:23px 18px;margin:18px 0 24px}.avatar{width:52px;height:52px;background:#edf2ff;border-radius:18px;display:flex;align-items:center;justify-content:center}.identity{display:flex;flex-direction:column;gap:7px;flex:1;min-width:0}.name{font-size:18px;font-weight:600}.status{font-size:11px;color:#8b95a6}.account-action{margin:0;background:#eef2ff;color:#294fdb;border-radius:10px;font-size:12px;padding:0 12px;line-height:34px}.permission-row,.web-update{background:#fff;border-radius:18px;display:flex;align-items:center;gap:12px;padding:14px;min-height:68px;margin-top:12px;box-shadow:0 6px 16px #14233308}.permission-row>text{flex:1;font-size:14px;font-weight:500}.row-icon{background:#f0f3f8;height:36px;width:36px;display:flex;align-items:center;justify-content:center;border-radius:11px}.web-update{justify-content:space-between;font-size:14px;font-weight:500}.version{display:block;font-size:11px;color:#8791a4;margin-top:5px;font-weight:400}.native-only{font-size:12px;color:#9aa4b5;padding-right:4px}</style>